"""Derived names and host ports for the local vLLM-SR runtime stack."""

from __future__ import annotations

import os
import re
from dataclasses import dataclass

from cli.consts import (
    DEFAULT_API_PORT,
    DEFAULT_DASHBOARD_PORT,
    DEFAULT_FLEET_SIM_PORT,
    DEFAULT_METRICS_PORT,
    DEFAULT_MILVUS_PORT,
    DEFAULT_ROUTER_PORT,
    DEFAULT_STACK_NAME,
    VLLM_SR_SIM_CONTAINER_NAME,
)

STACK_NAME_ENV = "VLLM_SR_STACK_NAME"
PORT_OFFSET_ENV = "VLLM_SR_PORT_OFFSET"

DEFAULT_JAEGER_OTLP_PORT = 4318
DEFAULT_JAEGER_UI_PORT = 16686
DEFAULT_PROMETHEUS_PORT = 9090
DEFAULT_GRAFANA_PORT = 3000
DEFAULT_REDIS_PORT = 6379
DEFAULT_POSTGRES_PORT = 5432

STACK_NAME_PATTERN = re.compile(r"[^A-Za-z0-9_.-]+")


@dataclass(frozen=True)
class RuntimeStackLayout:
    stack_name: str
    port_offset: int
    router_container_name: str
    envoy_container_name: str
    dashboard_container_name: str
    fleet_sim_container_name: str
    network_name: str
    jaeger_container_name: str
    prometheus_container_name: str
    grafana_container_name: str
    redis_container_name: str
    postgres_container_name: str
    milvus_container_name: str
    router_port: int
    metrics_port: int
    dashboard_port: int
    api_port: int
    fleet_sim_port: int
    jaeger_otlp_port: int
    jaeger_ui_port: int
    prometheus_port: int
    grafana_port: int
    redis_port: int
    postgres_port: int
    milvus_port: int

    @property
    def dashboard_url(self) -> str:
        return f"http://localhost:{self.dashboard_port}"

    @property
    def dashboard_service_url(self) -> str:
        return f"http://{self.dashboard_container_name}:8700"

    @property
    def metrics_url(self) -> str:
        return f"http://localhost:{self.metrics_port}/metrics"

    @property
    def router_api_service_url(self) -> str:
        return f"http://{self.router_container_name}:8080"

    @property
    def router_metrics_service_url(self) -> str:
        return f"http://{self.router_container_name}:9190/metrics"

    @property
    def envoy_admin_service_url(self) -> str:
        return f"http://{self.envoy_container_name}:9901"

    def envoy_listener_service_url(self, listener_port: int) -> str:
        return f"http://{self.envoy_container_name}:{listener_port}"

    @property
    def jaeger_ui_url(self) -> str:
        return f"http://localhost:{self.jaeger_ui_port}"

    @property
    def grafana_url(self) -> str:
        return f"http://localhost:{self.grafana_port}"

    @property
    def prometheus_url(self) -> str:
        return f"http://localhost:{self.prometheus_port}"

    @property
    def fleet_sim_url(self) -> str:
        return f"http://localhost:{self.fleet_sim_port}"

    @property
    def jaeger_service_url(self) -> str:
        return f"http://{self.jaeger_container_name}:16686"

    @property
    def prometheus_service_url(self) -> str:
        return f"http://{self.prometheus_container_name}:9090"

    @property
    def grafana_service_url(self) -> str:
        return f"http://{self.grafana_container_name}:3000"

    @property
    def fleet_sim_service_url(self) -> str:
        return f"http://{self.fleet_sim_container_name}:8000"

    @property
    def otlp_service_endpoint(self) -> str:
        return f"http://{self.jaeger_container_name}:4317"

    @property
    def redis_url(self) -> str:
        return f"localhost:{self.redis_port}"

    @property
    def postgres_url(self) -> str:
        return f"localhost:{self.postgres_port}"

    @property
    def milvus_url(self) -> str:
        return f"localhost:{self.milvus_port}"

    @property
    def milvus_service_url(self) -> str:
        return f"{self.milvus_container_name}:19530"

    @property
    def storage_container_names(self) -> tuple[str, ...]:
        return (
            self.redis_container_name,
            self.postgres_container_name,
            self.milvus_container_name,
        )

    @property
    def runtime_container_names(self) -> tuple[str, ...]:
        return tuple(
            dict.fromkeys(
                (
                    self.router_container_name,
                    self.envoy_container_name,
                    self.dashboard_container_name,
                )
            )
        )

    def service_container_name(self, service: str) -> str:
        if service == "router":
            return self.router_container_name
        if service == "envoy":
            return self.envoy_container_name
        if service == "dashboard":
            return self.dashboard_container_name
        if service == "simulator":
            return self.fleet_sim_container_name
        raise KeyError(f"unknown runtime service: {service}")


def resolve_runtime_stack(
    *, stack_name: str | None = None, port_offset: int | None = None
) -> RuntimeStackLayout:
    resolved_stack_name = normalize_stack_name(
        stack_name if stack_name is not None else os.getenv(STACK_NAME_ENV)
    )
    resolved_port_offset = normalize_port_offset(
        port_offset if port_offset is not None else os.getenv(PORT_OFFSET_ENV)
    )

    if resolved_stack_name == DEFAULT_STACK_NAME:
        router_container_name = "vllm-sr-router-container"
        envoy_container_name = "vllm-sr-envoy-container"
        dashboard_container_name = "vllm-sr-dashboard-container"
        fleet_sim_container_name = VLLM_SR_SIM_CONTAINER_NAME
        network_name = f"{DEFAULT_STACK_NAME}-network"
        jaeger_container_name = f"{DEFAULT_STACK_NAME}-jaeger"
        prometheus_container_name = f"{DEFAULT_STACK_NAME}-prometheus"
        grafana_container_name = f"{DEFAULT_STACK_NAME}-grafana"
        redis_container_name = f"{DEFAULT_STACK_NAME}-redis"
        postgres_container_name = f"{DEFAULT_STACK_NAME}-postgres"
        milvus_container_name = f"{DEFAULT_STACK_NAME}-milvus"
    else:
        router_container_name = f"{resolved_stack_name}-vllm-sr-router-container"
        envoy_container_name = f"{resolved_stack_name}-vllm-sr-envoy-container"
        dashboard_container_name = f"{resolved_stack_name}-vllm-sr-dashboard-container"
        fleet_sim_container_name = f"{resolved_stack_name}-vllm-sr-sim"
        network_name = f"{resolved_stack_name}-vllm-sr-network"
        jaeger_container_name = f"{resolved_stack_name}-vllm-sr-jaeger"
        prometheus_container_name = f"{resolved_stack_name}-vllm-sr-prometheus"
        grafana_container_name = f"{resolved_stack_name}-vllm-sr-grafana"
        redis_container_name = f"{resolved_stack_name}-vllm-sr-redis"
        postgres_container_name = f"{resolved_stack_name}-vllm-sr-postgres"
        milvus_container_name = f"{resolved_stack_name}-vllm-sr-milvus"

    return RuntimeStackLayout(
        stack_name=resolved_stack_name,
        port_offset=resolved_port_offset,
        router_container_name=router_container_name,
        envoy_container_name=envoy_container_name,
        dashboard_container_name=dashboard_container_name,
        fleet_sim_container_name=fleet_sim_container_name,
        network_name=network_name,
        jaeger_container_name=jaeger_container_name,
        prometheus_container_name=prometheus_container_name,
        grafana_container_name=grafana_container_name,
        redis_container_name=redis_container_name,
        postgres_container_name=postgres_container_name,
        milvus_container_name=milvus_container_name,
        router_port=DEFAULT_ROUTER_PORT + resolved_port_offset,
        metrics_port=DEFAULT_METRICS_PORT + resolved_port_offset,
        dashboard_port=DEFAULT_DASHBOARD_PORT + resolved_port_offset,
        api_port=DEFAULT_API_PORT + resolved_port_offset,
        fleet_sim_port=DEFAULT_FLEET_SIM_PORT + resolved_port_offset,
        jaeger_otlp_port=DEFAULT_JAEGER_OTLP_PORT + resolved_port_offset,
        jaeger_ui_port=DEFAULT_JAEGER_UI_PORT + resolved_port_offset,
        prometheus_port=DEFAULT_PROMETHEUS_PORT + resolved_port_offset,
        grafana_port=DEFAULT_GRAFANA_PORT + resolved_port_offset,
        redis_port=DEFAULT_REDIS_PORT + resolved_port_offset,
        postgres_port=DEFAULT_POSTGRES_PORT + resolved_port_offset,
        milvus_port=DEFAULT_MILVUS_PORT + resolved_port_offset,
    )


def normalize_stack_name(raw_value: str | None) -> str:
    """Return the one stack identity shared by every local runtime namespace.

    Missing or blank input selects the default stack. Distinct raw inputs that
    normalize to the same value intentionally alias one stack; a nonblank value
    with no usable ASCII identity fails instead of silently selecting default.
    """
    if raw_value is None:
        return DEFAULT_STACK_NAME
    stripped = raw_value.strip()
    if not stripped:
        return DEFAULT_STACK_NAME
    cleaned = STACK_NAME_PATTERN.sub("-", stripped).strip("._-")
    if not cleaned:
        raise ValueError(
            f"{STACK_NAME_ENV} must contain at least one ASCII letter or digit"
        )
    return cleaned


def normalize_port_offset(raw_value: str | int | None) -> int:
    if raw_value in (None, ""):
        return 0
    offset = int(raw_value)
    if offset < 0:
        raise ValueError(f"{PORT_OFFSET_ENV} must be >= 0, got {offset}")
    return offset

"""Helpers for selecting the Intelligent Routing for Mixture-of-Models topology mode."""

from __future__ import annotations

import os

from cli.consts import (
    DEFAULT_RUNTIME_TOPOLOGY,
    RUNTIME_TOPOLOGY_ENV,
    RUNTIME_TOPOLOGY_SPLIT,
)

VALID_RUNTIME_TOPOLOGIES = (RUNTIME_TOPOLOGY_SPLIT,)


def resolve_runtime_topology(topology: str | None = None) -> str:
    raw_value = topology if topology is not None else os.getenv(RUNTIME_TOPOLOGY_ENV)
    if raw_value is None:
        return DEFAULT_RUNTIME_TOPOLOGY

    normalized = str(raw_value).strip().lower()
    if not normalized:
        return DEFAULT_RUNTIME_TOPOLOGY
    if normalized not in VALID_RUNTIME_TOPOLOGIES:
        raise ValueError(
            f"Unsupported runtime topology '{raw_value}'. "
            f"{RUNTIME_TOPOLOGY_ENV} may be unset or set to "
            f"'{RUNTIME_TOPOLOGY_SPLIT}'."
        )
    return RUNTIME_TOPOLOGY_SPLIT


def split_runtime_enabled(topology: str | None = None) -> bool:
    resolve_runtime_topology(topology)
    return True

"""Runtime-oriented Click command entrypoints."""

from __future__ import annotations

import webbrowser
from pathlib import Path

import click

from cli.bootstrap import (
    ensure_bootstrap_workspace,
)
from cli.commands.common import exit_with_logged_error
from cli.commands.runtime_config_mutation import (
    ALGORITHM_TYPES,
)
from cli.commands.runtime_config_mutation import (
    inject_algorithm_into_config as _inject_algorithm_into_config,
)
from cli.commands.runtime_help import SERVE_HELP
from cli.commands.runtime_support import (
    append_passthrough_env_vars,
    apply_container_runtime_override,
    apply_runtime_mode_env_vars,
    configure_runtime_override_env_vars,
    log_bootstrap_result,
    resolve_effective_config_path,
    validate_setup_mode_flags,
)
from cli.consts import (
    DEFAULT_IMAGE_PULL_POLICY,
    IMAGE_PULL_POLICY_ALWAYS,
    IMAGE_PULL_POLICY_IF_NOT_PRESENT,
    IMAGE_PULL_POLICY_NEVER,
    SUPPORTED_CONTAINER_RUNTIMES,
    VLLM_SR_CONTAINER_IMAGE_DEFAULT,
)
from cli.deployment_backend import DEFAULT_TARGET, VALID_TARGETS, resolve_target
from cli.utils import get_logger

log = get_logger(__name__)


def inject_algorithm_into_config(config_path: Path, algorithm: str) -> Path:
    """Compatibility wrapper for callers importing from cli.commands.runtime."""
    return _inject_algorithm_into_config(config_path, algorithm)


TARGET_HELP = (
    f"Deployment target: {', '.join(VALID_TARGETS)} (default: {DEFAULT_TARGET})"
)

RUNTIME_HELP = (
    "Container runtime for the local Docker target: "
    f"{', '.join(SUPPORTED_CONTAINER_RUNTIMES)}. "
    "Equivalent to setting CONTAINER_RUNTIME=<runtime>. Has no effect on the k8s target."
)


def _build_backend(target: str | None, **k8s_kwargs):
    """Instantiate the right DeploymentBackend for *target*."""
    resolved = resolve_target(target)
    if resolved == "k8s":
        from cli.k8s_backend import K8sBackend  # noqa: PLC0415

        return K8sBackend(**{k: v for k, v in k8s_kwargs.items() if v is not None})

    from cli.container_backend import ContainerBackend  # noqa: PLC0415

    return ContainerBackend()


def _execute_serve(
    config: str,
    image: str | None,
    router_image: str | None,
    envoy_image: str | None,
    dashboard_image: str | None,
    sim_image: str | None,
    image_pull_policy: str,
    readonly: bool,
    minimal: bool,
    log_level: str | None,
    platform: str | None,
    algorithm: str | None,
    target: str | None,
    namespace: str | None,
    context: str | None,
    profile: str | None,
    chart_dir: str | None,
    runtime: str | None,
) -> None:
    """Bootstrap workspace, resolve config, and delegate to the deployment backend."""
    apply_container_runtime_override(runtime)
    requested_config = config
    bootstrap = ensure_bootstrap_workspace(Path(config))
    config_path = bootstrap.config_path
    setup_mode = bootstrap.setup_mode

    log_bootstrap_result(requested_config, bootstrap)
    log.info(f"Using config file: {config_path}")

    validate_setup_mode_flags(setup_mode, minimal, readonly)

    env_vars: dict[str, str] = {}
    append_passthrough_env_vars(env_vars)
    apply_runtime_mode_env_vars(
        env_vars,
        minimal,
        readonly,
        setup_mode,
        platform,
        algorithm,
        log_level=log_level,
    )

    effective_config_path = resolve_effective_config_path(
        config_path, algorithm, setup_mode, platform
    )
    configure_runtime_override_env_vars(env_vars, config_path, effective_config_path)

    backend = _build_backend(
        target,
        namespace=namespace,
        context=context,
        profile=profile,
        chart_dir=chart_dir,
    )
    backend.deploy(
        config_file=str(effective_config_path.absolute()),
        source_config_file=str(config_path.absolute()),
        runtime_config_file=str(effective_config_path.absolute()),
        env_vars=env_vars,
        image=image,
        router_image=router_image,
        envoy_image=envoy_image,
        dashboard_image=dashboard_image,
        sim_image=sim_image,
        pull_policy=image_pull_policy,
        enable_observability=not minimal,
    )


@click.command(help=SERVE_HELP)
@click.option(
    "--config",
    default="config.yaml",
    help="Path to config file (default: config.yaml)",
)
@click.option(
    "--image",
    default=None,
    help=f"Docker image to use (default: {VLLM_SR_CONTAINER_IMAGE_DEFAULT})",
)
@click.option(
    "--router-image",
    default=None,
    help="Docker image for the router container (Docker target only; defaults to --image or VLLM_SR_IMAGE)",
)
@click.option(
    "--envoy-image",
    default=None,
    help="Docker image for the Envoy container (Docker target only; defaults to --image or VLLM_SR_IMAGE)",
)
@click.option(
    "--dashboard-image",
    default=None,
    help="Docker image for the dashboard container (Docker target only; defaults to --image or VLLM_SR_IMAGE)",
)
@click.option(
    "--sim-image",
    default=None,
    help="Docker image for the simulator sidecar (Docker target only; defaults to VLLM_SR_SIM_IMAGE)",
)
@click.option(
    "--image-pull-policy",
    type=click.Choice(
        [
            IMAGE_PULL_POLICY_ALWAYS,
            IMAGE_PULL_POLICY_IF_NOT_PRESENT,
            IMAGE_PULL_POLICY_NEVER,
        ],
        case_sensitive=False,
    ),
    default=DEFAULT_IMAGE_PULL_POLICY,
    help=f"Image pull policy: always, ifnotpresent, never (default: {DEFAULT_IMAGE_PULL_POLICY})",
)
@click.option(
    "--readonly",
    is_flag=True,
    default=False,
    help="Run dashboard in read-only mode (disable config editing, allow playground only)",
)
@click.option(
    "--minimal",
    is_flag=True,
    default=False,
    help="Start in minimal mode: only router + envoy, no dashboard or observability (Jaeger, Prometheus, Grafana)",
)
@click.option(
    "--log-level",
    type=click.Choice(
        ["debug", "info", "warn", "warning", "error", "dpanic", "panic", "fatal"],
        case_sensitive=False,
    ),
    default=None,
    help="Router log level override (debug, info, warn, error, dpanic, panic, fatal)",
)
@click.option(
    "--platform",
    default=None,
    help="Platform for GPU deployments: 'amd' enables ROCm passthrough, "
    "'nvidia' enables NVIDIA GPU passthrough (--gpus all). "
    "When set to amd or nvidia, serve defaults to the matching GPU image "
    "(ROCm / CUDA) and flips use_cpu to false for router internal models under "
    "global.model_catalog, unless --image or VLLM_SR_IMAGE is provided. "
    "Set VLLM_SR_<PLATFORM>_PRESERVE_CPU=1 to keep CPU settings.",
)
@click.option(
    "--algorithm",
    type=click.Choice(ALGORITHM_TYPES, case_sensitive=False),
    default=None,
    help="Request-time base algorithm override: static, router_dc, automix, hybrid, "
    "workflows, latency_aware, knn, kmeans, svm, mlp, or multi_factor. "
    "Cross-request learning uses global.router.learning.adaptation/protection.",
)
@click.option("--target", default=None, help=TARGET_HELP)
@click.option(
    "--namespace", default=None, help="Kubernetes namespace (k8s target only)"
)
@click.option(
    "--context", default=None, help="kubectl / Helm context (k8s target only)"
)
@click.option(
    "--profile",
    default=None,
    help="Deployment profile: dev, prod (k8s target only). Selects values-<profile>.yaml defaults.",
)
@click.option(
    "--chart-dir", default=None, help="Path to Helm chart directory (k8s target only)"
)
@click.option(
    "--runtime",
    type=click.Choice(SUPPORTED_CONTAINER_RUNTIMES, case_sensitive=False),
    default=None,
    help=RUNTIME_HELP,
)
@exit_with_logged_error(log, interrupt_message="\nInterrupted by user")
def serve(
    config: str,
    image: str | None,
    router_image: str | None,
    envoy_image: str | None,
    dashboard_image: str | None,
    sim_image: str | None,
    image_pull_policy: str,
    readonly: bool,
    minimal: bool,
    log_level: str | None,
    platform: str | None,
    algorithm: str | None,
    target: str | None,
    namespace: str | None,
    context: str | None,
    profile: str | None,
    chart_dir: str | None,
    runtime: str | None,
) -> None:
    _execute_serve(
        config,
        image,
        router_image,
        envoy_image,
        dashboard_image,
        sim_image,
        image_pull_policy,
        readonly,
        minimal,
        log_level,
        platform,
        algorithm,
        target,
        namespace,
        context,
        profile,
        chart_dir,
        runtime,
    )


@click.command()
@click.argument(
    "service",
    type=click.Choice(["envoy", "router", "dashboard", "simulator", "all"]),
    default="all",
)
@click.option("--target", default=None, help=TARGET_HELP)
@click.option(
    "--namespace", default=None, help="Kubernetes namespace (k8s target only)"
)
@click.option(
    "--context", default=None, help="kubectl / Helm context (k8s target only)"
)
@click.option(
    "--runtime",
    type=click.Choice(SUPPORTED_CONTAINER_RUNTIMES, case_sensitive=False),
    default=None,
    help=RUNTIME_HELP,
)
@exit_with_logged_error(log)
def status(
    service: str,
    target: str | None,
    namespace: str | None,
    context: str | None,
    runtime: str | None,
) -> None:
    """
    Show status of vLLM Semantic Router services.

    Examples:
        vllm-sr status              # Show all services (Docker)
        vllm-sr status all          # Show all services
        vllm-sr status router       # Show router status
        vllm-sr status dashboard    # Show dashboard status
        vllm-sr status simulator    # Show simulator status
        vllm-sr status --target k8s # Show Kubernetes status
    """
    apply_container_runtime_override(runtime)
    backend = _build_backend(target, namespace=namespace, context=context)
    backend.status(service)


@click.command()
@click.argument(
    "service", type=click.Choice(["envoy", "router", "dashboard", "simulator"])
)
@click.option("--follow", "-f", is_flag=True, help="Follow log output")
@click.option("--target", default=None, help=TARGET_HELP)
@click.option(
    "--namespace", default=None, help="Kubernetes namespace (k8s target only)"
)
@click.option(
    "--context", default=None, help="kubectl / Helm context (k8s target only)"
)
@click.option(
    "--runtime",
    type=click.Choice(SUPPORTED_CONTAINER_RUNTIMES, case_sensitive=False),
    default=None,
    help=RUNTIME_HELP,
)
@exit_with_logged_error(log, interrupt_message="\nLog streaming stopped")
def logs(
    service: str,
    follow: bool,
    target: str | None,
    namespace: str | None,
    context: str | None,
    runtime: str | None,
) -> None:
    """
    Show logs from vLLM Semantic Router service.

    Examples:
        vllm-sr logs envoy
        vllm-sr logs router
        vllm-sr logs dashboard
        vllm-sr logs simulator
        vllm-sr logs envoy --follow
        vllm-sr logs router -f
        vllm-sr logs router --target k8s        # Kubernetes logs
        vllm-sr logs router --target k8s -f     # Follow K8s logs
    """
    apply_container_runtime_override(runtime)
    backend = _build_backend(target, namespace=namespace, context=context)
    backend.logs(service, follow=follow)


@click.command()
@click.option("--target", default=None, help=TARGET_HELP)
@click.option(
    "--namespace", default=None, help="Kubernetes namespace (k8s target only)"
)
@click.option(
    "--context", default=None, help="kubectl / Helm context (k8s target only)"
)
@click.option(
    "--runtime",
    type=click.Choice(SUPPORTED_CONTAINER_RUNTIMES, case_sensitive=False),
    default=None,
    help=RUNTIME_HELP,
)
@exit_with_logged_error(log)
def stop(
    target: str | None,
    namespace: str | None,
    context: str | None,
    runtime: str | None,
) -> None:
    """
    Stop vLLM Semantic Router.

    Examples:
        vllm-sr stop                # Stop Docker stack
        vllm-sr stop --target k8s   # Uninstall Helm release
    """
    apply_container_runtime_override(runtime)
    backend = _build_backend(target, namespace=namespace, context=context)
    backend.teardown()


@click.command()
@click.option("--no-open", is_flag=True, help="Don't open browser, just show URL")
@click.option("--target", default=None, help=TARGET_HELP)
@click.option(
    "--namespace", default=None, help="Kubernetes namespace (k8s target only)"
)
@click.option(
    "--context", default=None, help="kubectl / Helm context (k8s target only)"
)
@click.option(
    "--runtime",
    type=click.Choice(SUPPORTED_CONTAINER_RUNTIMES, case_sensitive=False),
    default=None,
    help=RUNTIME_HELP,
)
@exit_with_logged_error(log)
def dashboard(
    no_open: bool,
    target: str | None,
    namespace: str | None,
    context: str | None,
    runtime: str | None,
) -> None:
    """
    Open the dashboard in your default web browser.

    Examples:
        vllm-sr dashboard                   # Docker dashboard
        vllm-sr dashboard --target k8s      # Show K8s dashboard URL
        vllm-sr dashboard --no-open
    """
    apply_container_runtime_override(runtime)
    backend = _build_backend(target, namespace=namespace, context=context)
    if not backend.is_running():
        raise ValueError("vLLM Semantic Router is not running")

    dashboard_url = backend.get_dashboard_url()
    if dashboard_url is None:
        log.info("Dashboard URL could not be determined")
        return

    if no_open:
        log.info(f"Dashboard URL: {dashboard_url}")
        return

    log.info(f"Opening dashboard: {dashboard_url}")
    webbrowser.open(dashboard_url)
    log.info("Dashboard opened in browser")

